    h, w = len(g), len(g[0])

    # Restore the regular frame.
    for r in range(h):
        for c in range(w):
            if g[r][c] == 0 and (r < 2 or c < 2):
                g[r][c] = 1
            elif g[r][c] == 0 and c == 2 and r >= 2:
                g[r][c] = 4
            elif g[r][c] == 0 and r == 2:
                g[r][c] = 4

    # Infer each row's repeating sequence from intact cells, then fill gaps.
    for r in range(3, h):
        known = [(c, g[r][c]) for c in range(3, w) if g[r][c] != 0]
        if not known:
            continue

        best_p, best_err = 1, float("inf")
        for p in range(2, 11):
            groups = {}
            for c, v in known:
                groups.setdefault(c % p, []).append(v)
            err = sum(len(vals) - max(vals.count(v) for v in set(vals))
                      for vals in groups.values())
            if (err, p) < (best_err, best_p):
                best_p, best_err = p, err

        groups = {}
        for c, v in known:
            groups.setdefault(c % best_p, []).append(v)
        pattern = {
            residue: max(set(vals), key=vals.count)
            for residue, vals in groups.items()
        }
        for c in range(3, w):
            if g[r][c] == 0:
                if c % best_p in pattern:
                    g[r][c] = pattern[c % best_p]
                else:
                    nc, nv = min(known, key=lambda x: abs(x[0] - c))
                    g[r][c] = nv

    return g
